private int parseEndOfLine(String headerPart, int end) {
    int nextCharIndex = end;
    boolean foundCr = false;
    while (nextCharIndex < headerPart.length()) {
        char currentChar = headerPart.charAt(nextCharIndex);
        if (currentChar == '\n') {
            foundCr = true;
            break;
        }
        if (currentChar == '\r') {
            foundCr = true;
        }
        nextCharIndex++;
    }
    return foundCr ? nextCharIndex : headerPart.length();
}
