    private final long FETCH_DATA_DURATION;

    public TimeRangeBuilder(long FETCH_DATA_DURATION) {
        this.FETCH_DATA_DURATION = FETCH_DATA_DURATION;
    }

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        if (start + FETCH_DATA_DURATION <= end) {
            timeRanges.add(new TimeRange(start, end));
        } else {
            timeRanges.add(new TimeRange(start, FETCH_DATA_DURATION));
            timeRanges.add(new TimeRange(start + FETCH_DATA_DURATION, end));
        }
        return timeRanges;
    }

    public static void main(String[] args) {
        TimeRangeBuilder builder = new TimeRangeBuilder(60000); // One minute
        List<TimeRange> timeRanges = builder.buildTimeRanges(0, 180000);
        for (TimeRange range : timeRanges) {
            System.out.println("Start: " + range.getStart() + ", End: " + range.getEnd());
