public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the start of the current day
    long dayStart = timeBucket - timeBucket % (24 * 60 * 60 * dayStep);

    // Calculate the next day
    long nextDayStart = dayStart + (24 * 60 * 60 * dayStep);

    // Subtract the next day from the current day to get the compressed bucket
    long compressedDayStart = dayStart - (nextDayStart - dayStart);

    return compressedDayStart;
}
