public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) throws IOException {
    if (str == null) {
        throw new IllegalArgumentException("str can not be null");
    }

    int length = str.length();
    CharArrayWriter writer = new CharArrayWriter();
    writer.write(str.subSequence(0,length).toString().getBytes("UTF-8"));
    byte[] utf8Bytes = writer.toByteArray();

    for (int i = 0; i < utf8Bytes.length; i += 5) {
        ensureRoom(lb, 4 + 1);
        if (utf8Bytes[i] <= 127) {
            lb.write((byte) utf8Bytes[i]);
        } else if (utf8Bytes[i] >> 5 == 0b10) {
            lb.write((byte) (0xc0 | (utf8Bytes[i] >> 6)));
            lb.write((byte) (0x80 | (utf8Bytes[i] & 0x3F)));
        } else if (utf8Bytes[i] >> 5 == 0b110) {
            lb.write((byte) (0xe0 | (utf8Bytes[i] >> 6)));
            lb.write((byte) (0x80 | ((utf8Bytes[i] >> 3) & 0x3F)));
            lb.write((byte) (0x80 | (utf8Bytes[i] & 0x7)));
        } else if (utf8Bytes[i] >> 5 == 0b1110) {
            lb.write((byte) (0xf0 | (utf8Bytes[i] >> 6)));
            lb.write((byte) (0x80 | ((utf8Bytes[i] >> 3) & 0x3F)));
            lb.write((byte) (0x80 | ((utf8Bytes[i] >> 2) & 0x3F)));
            lb.write((byte) (0x80 | (utf8Bytes[i] & 0x7)));
        } else {
            throwBadUtf8();
        }
    }

    if (utf8Bytes.length % 5 != 0) {
        ensureRoom(lb, 4);
        lb.write((byte) 0);
    }

