public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    int i = desiredCapacity + 1;
    while (true) {
        if (isPrime(i) && isClose(i, desiredCapacity)) {
            return i;
