private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;

    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

private static boolean isClose(int a, int b) {
    if (a >= 1000) {
        return Math.abs((a * 110) - b) <= a * 10;
    } else {
        return Math.abs(a - b) <= a;
    }
}
