public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    StringBuilder result = new StringBuilder();
    int quotesState = 0;
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 < str.length()) {
                char nextCh = str.charAt(i + 1);
                if (nextCh == '\'' && quotesState == 0) {
                    result.append(nextCh); // Skip single quotes
                    i--; // Skip the \', since we'll append the next character anyway
                } else {
                    switch (nextCh) {
                        case 'b':
                            result.append('\b');
                            break;
                        case 'f':
                            result.append('\f');
                            break;
                        case 'n':
                            result.append('\n');
                            break;
                        case 'r':
                            result.append('\r');
                            break;
                        case 't':
                            result.append('\t');
                            break;
                        case 'u':
                            // Convert Unicode escape sequence
                            if (i + 5 < str.length()) {
                                String unicodeStr = str.substring(i + 2, i + 6);
                                result.append((char) Integer.parseInt(unicodeStr, 16));
                                i += 5; // Skip the entire unicode escape sequence
                            }
                            break;
                        default:
                            throw new IllegalStateException("Unhandled escape sequence '" + nextCh + "'");
                    }
                    i++; // Skip the \, since we processed the character
                }
            } else {
                throw new IllegalStateException("Escape sequence \\\u but no next character");
            }
        } else {
            if (quotesState == 0 && ((ch == '\'' && nextCh == '\'' && i > 0) || (ch == '\"' && nextCh == '\"' && i > 0))) {
                // Skip double quotes
                i++;
            }
            result.append(ch);
        }
    }
    return result.toString();
}
