import java.nio.charset.StandardCharsets;

public class ByteVector {
    private final byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[0];
        this.length = 0;
    }

    public ByteVector addBytes(byte[] bytes) {
        int newLength = this.length + bytes.length;
        if (newLength > this.data.length) {
            enlarge(newLength);
        }
        System.arraycopy(bytes, 0, this.data, this.length, bytes.length);
        this.length = newLength;
        return this;
    }

    public ByteVector put11(int byteValue1, int byteValue2) {
        int newLength = this.length + 2;
        if (newLength > this.data.length) {
            enlarge(newLength);
        }
        this.data[this.length++] = (byte) byteValue1;
        this.data[this.length++] = (byte) (byteValue2 >> 8);
        return this;
    }

    private void enlarge(int minCapacity) {
        int newLength = Math.max(this.data.length * 2, minCapacity);
        byte[] newData = new byte[newLength];
        System.arraycopy(this.data, 0, newData, 0, this.length);
        this.data = newData;
    }
}
